pub async fn register_blob_vectors_tools(
    registry: &ToolRegistry,
    qdrant: Option<Arc<QdrantSemanticShuttle>>,
) -> Result<()> {
    registry
        .register(Arc::new(RefreshBlobVectorsTool {
            shuttle: qdrant.clone(),
        }) as BoxedTool)
        .await?;
