#[cfg(test)]
mod tests {
    use super::*;

    use tonic::Code;

    #[test]
    fn add_folder_denies_untrusted_path_before_filesystem_access() {
        for path in ["/etc", "../private", "/tmp/linked-root"] {
            let request = Request::new(AddFolderRequest {
                notebook_id: "caller-supplied".into(),
                folder_path: path.into(),
                patterns: vec![],
                recursive: true,
            });
            assert_eq!(
                require_add_folder_admission(&request).unwrap_err().code(),
                Code::PermissionDenied
            );
        }
    }

    #[test]
    fn should_glob_match_star() {
        assert!(glob_match("*.rs", "main.rs"));
        assert!(glob_match("*.rs", "lib.rs"));
        assert!(!glob_match("*.rs", "main.py"));
    }

    #[test]
    fn should_glob_match_question() {
        assert!(glob_match("?.rs", "a.rs"));
        assert!(!glob_match("?.rs", "ab.rs"));
    }

    #[test]
    fn should_glob_match_exact() {
        assert!(glob_match("main.rs", "main.rs"));
        assert!(!glob_match("main.rs", "lib.rs"));
    }
}

//! Operator CLI for the snowball vector pipeline (`snowball_footprints` only).
//!
//! Strict automatic Qdrant policy applies **only** to this collection — not to
//! `blob_vectors`, user_memory, or RAG shuttle traffic.
//!
//! Origin host (has a Voyage key):
//! ```sh
//! op-chain-vectors status
//! op-chain-vectors project --limit 50              # embed → btrfs vectors only (no Qdrant)
//! op-chain-vectors project --limit 50 --upsert-qdrant  # manual: also write Qdrant directly
//! op-chain-vectors replicate --snapshot /prepared/golden-ro --host offsite.example --remote-path /prepared/receive
//! ```
//!

//! op-chain-vectors project --limit 50 --upsert-qdrant  # manual: also write Qdrant directly
//! op-chain-vectors replicate --snapshot /prepared/golden-ro --host offsite.example --remote-path /prepared/receive
//! ```
//!
//! Replica host (no Voyage key needed):
//! ```sh
//! op-chain-vectors ingest                  # Qdrant upsert after btrfs receive (automatic path)
//! ```
//!
//! Configuration is env-driven and shared with the rest of the workspace:
//! `OPDBUS_SNOWBALL_PATH`, `OPDBUS_QDRANT_URL` (or `COGNITIVE_QDRANT_URL`),
//! `OPDBUS_QDRANT_SNOWBALL_COLLECTION`, `OPDBUS_QDRANT_SNOWBALL_DIM`.

use anyhow::{Context, Result};
use clap::{Parser, Subcommand};
use op_cognitive::ChainVectorIndex;

//! Snowball vector projection: chain block -> Voyage embedding -> chain
//! vector subvolume, with Qdrant filled on the replica after `btrfs receive`.
//!
//! **Strict automatic invariant:** the streaming / default `project` path must
//! **not** upsert Qdrant on the origin. Vectors land in the chain first
//! ([`StreamingSnowball::attach_vector`] / `vectors/vec-*.bin`); the automatic
//! pipeline fills `snowball_footprints` only via **`btrfs receive` →
//! [`ChainVectorIndex::ingest_received`]** (replica hook). Orthogonal paths
//! (`blob_vectors`, user_memory, RAG shuttle) are unrelated and untouched.
//!
//! Split by role:
//!
//! - **Origin, automatic** ([`ChainVectorIndex::project_pending`] with
//!   `upsert_qdrant = false`): embed pending blocks with Voyage, write raw LE
//!   f32 into the `vectors` subvolume, stop. No Qdrant write, no index
//!   watermark bump. Snapshots carry the vectors to the replica.
//!
//! - **Replica, automatic** ([`ChainVectorIndex::ingest_received`]): after
//!   incremental `btrfs receive`, upsert only vectors that arrived (watermark +
//!   gap check). No Voyage key, no re-embedding.
//!
//! - **Manual exception** (`project_pending(..., upsert_qdrant = true)` /
//!   CLI `--upsert-qdrant`, or [`ChainVectorIndex::reindex_from_chain`]):
//!   explicit direct Qdrant write that **bypasses send/receive**. Not the
//!   default streaming path.
//!
//! Qdrant remains a disposable index: rebuild from any chain (or received
//! snapshot) that already holds the vectors.

use anyhow::{Context, Result};
use op_cozo_store::CozoGraphShuttle;

